// ---------------------------------------------------------------------------
// Provider: learning library — tutorials, cookbook, glossary, FAQ,
// troubleshooting, comparisons, class spotlight, recipes, layout patterns,
// accessibility, design guides, industry blueprints, team & ops guides.
// Version-aware where it matters, shared (with version framing) otherwise.
// ---------------------------------------------------------------------------
import { article, p, h2, h3, code, list, table, callout, cards, cap } from '../lib/model.mjs';

export function learningArticles(V) {
  const A = [];
  const isV1 = V.id === 'v1.0';

  // ================================================================ TUTORIALS
  A.push(seriesHub(V, 'tutorials/index', 'Tutorials', 'Step-by-step builds', tutorialSeries(V), 12));
  for (const [seriesSlug, seriesTitle, chapters] of tutorialSeries(V)) {
    for (let i = 0; i < chapters.length; i++) {
      const [slug, title, goal, steps] = chapters[i];
      A.push(article({
        slug: `tutorials/${seriesSlug}/${slug}`,
        title: `${title} — ${seriesTitle}`,
        section: 'tutorials',
        category: `Tutorials · ${seriesTitle}`,
        tags: ['tutorials', seriesSlug],
        keywords: [title.toLowerCase(), 'tutorial', seriesTitle.toLowerCase()],
        summary: `${goal} Chapter ${i + 1} of ${chapters.length} in the ${V.label} "${seriesTitle}" tutorial series.`,
        hub: 'tutorials/index',
        blocks: [
          p(`*${seriesTitle} — chapter ${i + 1} of ${chapters.length}.* ${goal}`),
          h2('What you will build'),
          p(steps.intro),
          h2('Step by step'),
          code(steps.lang || 'html', steps.code, steps.file || 'example'),
          h2('Why it works'),
          p(steps.why),
          h2('Try it yourself'),
          list(steps.try),
          h2('Series navigation'),
          p(seriesNav(seriesSlug, seriesTitle, chapters, i))
        ]
      }));
    }
  }

  // ================================================================= COOKBOOK
  A.push(seriesHub(V, 'cookbook/index', 'Cookbook', 'One problem, one solution', null, 14, cookbookPreview()));
  for (const [slug, title, problem, solution, lang, note] of COOKBOOK) {
    A.push(article({
      slug: `cookbook/${slug}`,
      title: `${title} — ${V.label} Cookbook`,
      section: 'cookbook',
      category: 'Cookbook',
      tags: ['cookbook', 'recipes'],
      keywords: [title.toLowerCase(), 'how to', 'cookbook', problem.toLowerCase()],
      summary: `${problem} The ${V.label} solution with code, explanation and variants.`,
      hub: 'cookbook/index',
      blocks: [
        p(`**Problem:** ${problem}`),
        h2('Solution'),
        code(lang || 'html', solution),
        h2('Why this works'),
        p(note),
        h2('Variants'),
        list(cookbookVariants(slug)),
        h2('Related recipes'),
        p('[[cookbook/index|Cookbook index]] · [[utilities/index|Utilities reference]] · [[patterns/index|Layout patterns]]')
      ]
    }));
  }

  // ============================================================= PATTERNS
  A.push(seriesHub(V, 'patterns/index', 'Layout patterns', 'Named, reusable layout recipes', null, 15, null));
  for (const [slug, title, desc, markup] of PATTERNS) {
    A.push(article({
      slug: `patterns/${slug}`,
      title: `${title} pattern — ${V.label}`,
      section: 'patterns',
      category: 'Layout Patterns',
      tags: ['patterns', 'layout'],
      keywords: [title.toLowerCase(), 'layout pattern', 'css pattern'],
      summary: `${desc} The complete ${V.label} implementation with responsive behavior.`,
      hub: 'patterns/index',
      blocks: [
        p(desc),
        h2('The pattern'),
        code('html', markup),
        h2('Responsive behavior'),
        p(patternResponsive(slug)),
        h2('When to use'),
        list(patternWhen(slug)),
        h2('Related patterns'),
        p('[[patterns/index|All patterns]] · [[utilities/grid/grid-template-columns|Grid]] · [[utilities/flexbox/flex-direction|Flexbox]]')
      ]
    }));
  }

  // ================================================================== RECIPES
  A.push(seriesHub(V, 'recipes/index', 'Recipes', 'Copy-paste components', null, 13, null));
  for (const [slug, title, desc, markup] of RECIPES) {
    A.push(article({
      slug: `recipes/${slug}`,
      title: `${title} — ${V.label} recipe`,
      section: 'recipes',
      category: 'Recipes',
      tags: ['recipes', 'components'],
      keywords: [title.toLowerCase(), 'component', 'recipe', 'copy paste'],
      summary: `${desc} A production-ready ${V.label} recipe you can copy today.`,
      hub: 'recipes/index',
      blocks: [
        p(desc),
        h2('The component'),
        code('html', markup),
        h2('Responsive & dark'),
        p(recipeDark(slug)),
        h2('Customization'),
        list(recipeCustom(slug)),
        h2('Related recipes'),
        p('[[recipes/index|Recipe index]] · [[components/index|Design components]]')
      ]
    }));
  }

  // ================================================================ GLOSSARY
  A.push(seriesHub(V, 'glossary/index', 'Glossary', 'Every term defined', null, 16, null));
  for (const [term, def, related] of GLOSSARY) {
    const slug = 'glossary/' + term.toLowerCase().replace(/[^a-z0-9]+/g, '-');
    A.push(article({
      slug,
      title: `${term} — Nakshora Glossary`,
      section: 'glossary',
      category: 'Glossary',
      tags: ['glossary', 'definitions'],
      keywords: [term.toLowerCase(), 'definition', 'glossary', 'what is'],
      summary: def.split('.')[0] + `. Definition and context from the ${V.label} glossary.`,
      hub: 'glossary/index',
      blocks: [
        p(`**${term}.** ${def}`),
        h2(`In ${V.label}`),
        p(glossaryInNakshora(term, V)),
        h2('See also'),
        p(related.map((r) => `[[glossary/${r.toLowerCase().replace(/[^a-z0-9]+/g, '-')}|${r}]]`).join(' · '))
      ]
    }));
  }

  // ===================================================================== FAQ
  A.push(article({
    slug: 'faq/index',
    title: `FAQ — ${V.label}`,
    section: 'faq',
    category: 'FAQ',
    tags: ['faq'],
    keywords: ['faq', 'questions', 'help'],
    summary: `The most frequently asked questions about ${V.label}, answered in depth: sizing, licensing, comparisons, workflow and edge cases.`,
    order: 20,
    blocks: [
      p(`Eighty questions we hear constantly about ${V.label} — each linked to its own deep-dive page.`),
      h2('Questions'),
      ...FAQ.flatMap(([q], i) => [p(`**Q${i + 1}.** [[faq/q${i + 1}|${q}]]`)]),
    ]
  }));
  for (let i = 0; i < FAQ.length; i++) {
    const [q, a] = FAQ[i];
    A.push(article({
      slug: `faq/q${i + 1}`,
      title: q,
      section: 'faq',
      category: 'FAQ',
      tags: ['faq'],
      keywords: [q.toLowerCase().slice(0, 60)],
      summary: a.slice(0, 150),
      hub: 'faq/index',
      blocks: [
        p(`**Question:** ${q}`),
        h2('Answer'),
        p(a),
        h2('Related questions'),
        p(`[[faq/index|FAQ index]] · [[troubleshooting/index|Troubleshooting]] · [[getting-started/introduction|Introduction]]`)
      ]
    }));
  }

  // ========================================================= TROUBLESHOOTING
  A.push(article({
    slug: 'troubleshooting/index',
    title: `Troubleshooting — ${V.label}`,
    section: 'troubleshooting',
    category: 'Troubleshooting',
    tags: ['troubleshooting'],
    keywords: ['troubleshooting', 'fix', 'error', 'not working'],
    summary: `The ${V.label} troubleshooting index: every known issue, its diagnosis and its fix.`,
    order: 21,
    blocks: [
      p(`When ${V.label} misbehaves, start here. Every issue links to a full diagnosis page.`),
      list(TROUBLE.map(([sym], i) => `[[troubleshooting/t${i + 1}|${sym}]]`)),
      callout('tip', V.jit ? 'Run `nakshora doctor` first — it automates half of this page.' : 'Clear caches and re-link the stylesheet before anything else.')
    ]
  }));
  for (let i = 0; i < TROUBLE.length; i++) {
    const [sym, cause, fix] = TROUBLE[i];
    A.push(article({
      slug: `troubleshooting/t${i + 1}`,
      title: `Fix: ${sym}`,
      section: 'troubleshooting',
      category: 'Troubleshooting',
      tags: ['troubleshooting'],
      keywords: [sym.toLowerCase().slice(0, 60), 'fix'],
      summary: `${sym} — why it happens in ${V.label} and the step-by-step fix.`,
      hub: 'troubleshooting/index',
      blocks: [
        p(`**Symptom:** ${sym}`),
        h2('Root cause'),
        p(cause),
        h2('The fix'),
        p(fix),
        h2('Verify'),
        list(['Hard-refresh (the CSS cache is the #1 false negative)', V.jit ? 'Run `nakshora doctor` and re-build with `--stats`' : 'Re-generate and re-link the stylesheet', 'Search the docs for the exact class — spelling is unforgiving']),
        h2('Related'),
        p('[[troubleshooting/index|All issues]] · [[faq/index|FAQ]]')
      ]
    }));
  }

  // ============================================================ COMPARISONS
  A.push(seriesHub(V, 'comparisons/index', 'Comparisons', 'Honest decision guides', null, 17, null));
  for (const [slug, title, verdict, points] of COMPARISONS) {
    A.push(article({
      slug: `comparisons/${slug}`,
      title: `${title} — ${V.label}`,
      section: 'comparisons',
      category: 'Comparisons',
      tags: ['comparisons', 'decisions'],
      keywords: [title.toLowerCase(), 'vs', 'comparison', 'difference'],
      summary: `${title} — the honest differences, when to pick which, and what ${V.label} does about it.`,
      hub: 'comparisons/index',
      blocks: [
        p(`**${title}** is one of the most common decision points we see. Here is the honest breakdown.`),
        h2('The short version'),
        p(verdict),
        h2('Point by point'),
        table(['Aspect', 'Analysis'], points),
        h2('Bottom line'),
        p(comparisonBottom(slug)),
        h2('Related comparisons'),
        p('[[comparisons/index|All comparisons]]')
      ]
    }));
  }

  // ================================================================ SPOTLIGHT
  A.push(seriesHub(V, 'spotlight/index', 'Class spotlight', 'The most-used classes, deeply explained', null, 18, null));
  for (const [cls, essay] of SPOTLIGHT) {
    const slug = 'spotlight/' + cls.replace(/[^a-z0-9]+/gi, '-').toLowerCase();
    A.push(article({
      slug,
      title: `${cls} — class spotlight`,
      section: 'spotlight',
      category: 'Class Spotlight',
      tags: ['spotlight', 'utilities'],
      keywords: [cls, 'class', 'spotlight', 'how to use'],
      summary: `Everything about \`${cls}\`: what it compiles to, ten ways to use it, and the mistakes everyone makes.`,
      hub: 'spotlight/index',
      blocks: [
        p(`\`${cls}\` is one of the highest-frequency classes in real Nakshora codebases. ${essay}`),
        h2('What it compiles to'),
        code('css', spotlightCss(cls, V)),
        h2('Ten ways to use it'),
        list(spotlightUses(cls)),
        h2('Common mistakes'),
        list(spotlightMistakes(cls)),
        h2('Related'),
        p(`[[spotlight/index|Spotlight index]] · [[utilities/index|Utilities reference]]`)
      ]
    }));
  }

  // ============================================================ ACCESSIBILITY
  A.push(seriesHub(V, 'accessibility/index', 'Accessibility', 'Ship inclusive interfaces', null, 19, null));
  for (const [slug, title, desc, body] of A11Y) {
    A.push(article({
      slug: `accessibility/${slug}`,
      title: `${title} — ${V.label} accessibility`,
      section: 'accessibility',
      category: 'Accessibility',
      tags: ['accessibility', 'a11y'],
      keywords: [title.toLowerCase(), 'accessibility', 'a11y', 'wcag'],
      summary: `${desc} Practical accessibility guidance with ${V.label} utilities.`,
      hub: 'accessibility/index',
      blocks: [
        p(desc),
        h2('The guidance'),
        p(body),
        h2('In markup'),
        code('html', a11yExample(slug)),
        h2('Checklist'),
        list(a11yChecklist(slug)),
        h2('Related'),
        p('[[accessibility/index|Accessibility hub]] · [[utilities/interactivity/sr-only|sr-only]]')
      ]
    }));
  }

  // ============================================================ DESIGN GUIDE
  A.push(seriesHub(V, 'design/index', 'Design guides', 'Taste, systematized', null, 22, null));
  for (const [slug, title, desc, body] of DESIGN) {
    A.push(article({
      slug: `design/${slug}`,
      title: `${title} — ${V.label} design guide`,
      section: 'design',
      category: 'Design Guides',
      tags: ['design', 'theory'],
      keywords: [title.toLowerCase(), 'design', 'guide'],
      summary: `${desc} A ${V.label} design guide with concrete class-level advice.`,
      hub: 'design/index',
      blocks: [p(desc), h2('Principles'), p(body), h2('Applied'), list(designApplied(slug)), h2('Related'), p('[[design/index|Design guides]] · [[themes/index|Themes]]')]
    }));
  }

  // ===================================================== INDUSTRY BLUEPRINTS
  A.push(seriesHub(V, 'blueprints/index', 'Industry blueprints', 'Full page structures by industry', null, 23, null));
  for (const [slug, industry, sections] of BLUEPRINTS) {
    A.push(article({
      slug: `blueprints/${slug}`,
      title: `${industry} landing page blueprint — ${V.label}`,
      section: 'blueprints',
      category: 'Blueprints',
      tags: ['blueprints', industry.toLowerCase()],
      keywords: [industry.toLowerCase(), 'landing page', 'blueprint', 'template'],
      summary: `A complete ${industry} landing page structure in ${V.label}: every section, the classes that build it, and the conversion rationale.`,
      hub: 'blueprints/index',
      blocks: [
        p(`A section-by-section blueprint for a ${industry} landing page. Copy the skeleton, swap the copy.`),
        h2('Page structure'),
        table(['Order', 'Section', 'Key classes'], sections),
        h2('Skeleton'),
        code('html', blueprintSkeleton(industry)),
        h2('Conversion notes'),
        list(blueprintNotes(industry)),
        h2('Related'),
        p('[[blueprints/index|All blueprints]] · [[recipes/index|Recipes]] · [[tutorials/index|Tutorials]]')
      ]
    }));
  }

  // ============================================================ TEAM & OPS
  for (const [slug, title, desc, points] of TEAM_OPS) {
    A.push(article({
      slug: `teams/${slug}`,
      title: `${title} — ${V.label}`,
      section: 'teams',
      category: 'Teams & Operations',
      tags: ['teams', 'process'],
      keywords: [title.toLowerCase(), 'teams', 'process'],
      summary: `${desc} Operational guidance for teams running ${V.label} at scale.`,
      blocks: [p(desc), h2('Playbook'), list(points), h2('Related'), p('[[performance/index|Performance]] · [[configuration/index|Configuration]]')]
    }));
  }

  // ================================================================ DEPLOY
  for (const [slug, title, steps] of DEPLOY) {
    A.push(article({
      slug: `deployment/${slug}`,
      title: `${title} — deploying a Nakshora site`,
      section: 'deployment',
      category: 'Deployment',
      tags: ['deployment', 'hosting'],
      keywords: [title.toLowerCase(), 'deploy', 'hosting'],
      summary: `Deploy your ${V.label} site to ${title}: exact settings, cache headers and verification.`,
      blocks: [
        p(`Nakshora output is static CSS — it deploys anywhere. Here is the exact ${title} recipe.`),
        h2('Steps'),
        list(steps),
        h2('Cache headers'),
        code('text', 'assets/*.css  →  public, max-age=31536000, immutable\n*.html        →  public, max-age=0, must-revalidate'),
        h2('Verify'),
        list(['Lighthouse ≥ 95 performance with a JIT build', 'No console 404s for CSS', 'Brotli/gzip enabled']),
        callout('note', 'This documentation platform itself runs on Cloudflare Pages — the same recipe, proven.')
      ]
    }));
  }
  return A;
}

// ===================================================================== DATA

function seriesHub(V, slug, title, tagline, series, order, preview) {
  const blocks = [
    p(`**${title}** — ${tagline}. ${series ? 'Series in this collection:' : 'Browse the collection below.'}`),
    ...(series ? [h2('Series'), cards(series.map(([s, t, ch]) => ({ slug: `tutorials/${s}/${ch[0][0]}`, title: t, desc: `${ch.length} chapters` })))] : []),
    ...(preview ? [h2('Popular entries'), cards(preview.map((s) => ({ slug: s, title: s.split('/').pop().replace(/-/g, ' '), desc: '' })))] : []),
    callout('tip', 'Everything here is version-aware: examples use the classes available in the docs version you are reading.')
  ];
  return article({
    slug,
    title: `${title} — ${V.label}`,
    section: slug.split('/')[0],
    category: title,
    tags: [slug.split('/')[0]],
    keywords: [title.toLowerCase(), V.label.toLowerCase()],
    summary: `${title} for ${V.label}: ${tagline.toLowerCase()}.`,
    order,
    blocks
  });
}

