function seriesNav(seriesSlug, seriesTitle, chapters, i) {
  const parts = [`[[tutorials/index|All tutorials]]`];
  if (i > 0) parts.push(`[[tutorials/${seriesSlug}/${chapters[i - 1][0]}|← ${chapters[i - 1][1]}]]`);
  if (i < chapters.length - 1) parts.push(`[[tutorials/${seriesSlug}/${chapters[i + 1][0]}|${chapters[i + 1][1]} →]]`);
  return parts.join(' · ');
}

