function glossaryInNakshora(term, V) {
  return `${V.label} embodies this concept throughout the platform — search the utilities reference and guides for concrete usage. The glossary links every term to its neighbors, so follow the chain to build a complete mental model of the framework.`;
}

// ===================================================================== FAQ
const FAQ = [
  ['What is Nakshora?', 'Nakshora (নক্ষত্র — “star” in Bangla) is a modern, ultra-fast, utility-first CSS framework with a JIT compiler, created by Rizwan Rahim Chowdhury and developed by RRC Development. You compose interfaces from small, documented classes; the compiler emits only the CSS you actually use.'],
  ['Is Nakshora free?', 'Yes — Nakshora is MIT licensed. Free for personal and commercial use, forever. No subscription, no attribution requirement.'],
  ['How is Nakshora different from Tailwind CSS?', 'Nakshora speaks the Tailwind 3.4 class grammar (verified byte-identical by a differential oracle) while adding built-in design paradigms (glass, neon, brutalist), five theme presets, ten breakpoints, and first-class AI artifacts. Migrating from Tailwind is one command: nakshora migrate.'],
  ['Can I use Nakshora with React/Vue/Svelte?', 'Yes. Nakshora is framework-agnostic: it outputs CSS. First-class integrations exist for Vite, PostCSS (webpack, Next.js, Laravel, Rails…) and a CLI for everything else.'],
  ['What is the bundle size?', 'JIT builds are typically 5–20 KB minified. The full CDN build is ~6 MB (133 KB brotli) — use it only for prototyping.'],
  ['Does Nakshora require JavaScript at runtime?', 'No. Nakshora is zero-runtime: it compiles to pure CSS. Any JS you ship is your application’s, not the framework’s.'],
  ['How do I use dark mode?', 'Pick a strategy: class-based (toggle a dark class on <html>), media-based (follow OS), or selector-based (3.1). Then use dark: variants: bg-white dark:bg-slate-950.'],
  ['What browsers are supported?', 'All evergreen browsers. Features like container queries degrade gracefully; supports-* variants let you enhance progressively.'],
  ['Is there a CDN?', 'Yes — jsDelivr serves both the current full build and the frozen v1.0.0 stylesheet. See the installation guide.'],
  ['How do I keep dynamically-created classes?', 'Add them to the safelist (plain strings or regex patterns). The scanner only protects what it can see in source.'],
  ['Why are my classes not being generated?', 'Almost always: (1) the file is outside your content globs, (2) the class name is built at runtime by concatenation, or (3) a misspelling. nakshora doctor diagnoses all three.'],
  ['Can I customize the theme?', 'Completely. theme.extend deep-merges your tokens over the defaults; presets package whole themes. CSS-first config (@theme) works too on 3.1.'],
  ['What are design components?', 'Ready-made paradigm classes: .glass, .neon-card, .brutalist-btn, .skeleton-rect. They compose with utilities like any other class.'],
  ['How do I migrate from v1?', 'v1 is frozen CSS. Install the CLI, copy site/nakshora.config.mjs to keep the v1 look, swap renamed components, and replace the link tag with your build output.'],
  ['How do I migrate from v2?', 'The CSSGenerator API survived intact. Replace the v2 dependency with @nakshora/core, add content globs to enable JIT, and enjoy fixed spacing/responsive bugs.'],
  ['How do I migrate from Tailwind?', 'npx nakshora migrate ports config, at-rules and dependencies. The class grammar is compatible — markup typically needs zero changes.'],
  ['Does Nakshora support RTL?', 'Yes — use logical utilities (ms-*, ps-*, border-s, text-start/end) and the rtl:/ltr: variants.'],
  ['Is there editor autocomplete?', 'Yes — nakshora lsp is a full language server: completions, hover CSS, diagnostics and color swatches for VS Code, Neovim, Zed, Helix, Sublime and JetBrains.'],
  ['What is the playground?', 'A browser-based compiler at nakshora.bsdc.info.bd/playground — type classes, see the CSS instantly, share URLs.'],
  ['Can Nakshora run in the browser?', 'Yes — @nakshora/core has zero Node dependencies; the playground runs the whole engine client-side.'],
  ['How fast are builds?', 'Cold JIT builds of a 200-line page take ~18 ms; incremental rebuilds ~1.3 ms thanks to the content cache.'],
  ['Why “Nakshora”?', 'Nakshora comes from নক্ষত্র (nokkhotro) — “star” in Bangla. The framework aspires to be a guiding star for utility-first development.'],
  ['Who maintains Nakshora?', 'Rizwan Rahim Chowdhury (owner & author) and RRC Development. Releases are automated via Changesets with provenance-signed npm publishing.'],
  ['How do I report a bug?', 'Open an issue on github.com/nakshora/nakshora with a playground link — one-click repros get the fastest fixes.'],
  ['Can I contribute?', 'Yes — the monorepo has a full contributing guide: pnpm workspace, vitest, ESLint 9, Prettier. Tests are required for engine changes.'],
  ['Is the documentation generated?', 'Partly: utility tables are generated from the compiler registry so they never drift. Guides, tutorials and recipes are authored.'],
  ['Does Nakshora have container queries?', 'Yes, since 3.1: @container, @min-*, @max-* variants respond to ancestor widths.'],
  ['What are arbitrary values?', 'Bracket syntax for one-offs: w-[37px], bg-[#1e293b], grid-cols-[1fr_2fr]. Prefer tokens when a value repeats.'],
  ['What are arbitrary properties?', 'Bracket declarations without a utility: [mask-type:luminance]. For everything the catalog misses.'],
  ['Does it support @apply?', 'Yes — @apply, theme() and screen() work in author CSS through all integrations.'],
  ['Can I disable parts of the framework?', 'Yes — corePlugins lets you turn off entire utility groups (object form) or allow-list what remains (array form).'],
  ['What is a preset?', 'A packaged configuration. presets: [companyTheme] shares a whole design system across apps.'],
  ['How do I add a custom color?', 'theme.extend.colors.brand = { 500: "#6d28d9" } — then use bg-brand-500 etc.'],
  ['How do I add a custom screen?', 'theme.extend.screens["3col"] = "1440px" — the new prefix works with all variants.'],
  ['How do I add a custom animation?', 'theme.extend.keyframes + theme.extend.animation; then use animate-yourname.'],
  ['Can I use Nakshora with WordPress?', 'Yes — either enqueue the CDN/frozen file or JIT-build with the CLI and enqueue the output.'],
  ['Does it work with email?', 'Partially: JIT builds keep CSS small enough for email clients, but client support for modern CSS varies — stick to basic utilities.'],
  ['What about print styles?', 'print: variants hide chrome and adjust colors: print:hidden, print:text-black.'],
  ['How do I make a sticky footer?', 'body: min-h-screen flex flex-col; main: flex-1. See the cookbook.'],
  ['How do I center a div?', 'grid place-items-center on the parent — one class pair. See the cookbook.'],
  ['Why is my z-index not working?', 'Stacking contexts. Transforms/opacity on an ancestor create a context that traps z-index inside. See the z-index guide.'],
  ['Why does text-align not center my flex items?', 'Flex uses justify-*/align-* for alignment; text-align only affects inline content.'],
  ['What is the spacing scale?', 'A rem progression: 0, px, 0.5, 1, 1.5, 2, 2.5, 3, 3.5, 4, 5, 6 … 96. p-4 = 1rem.'],
  ['Can I extend the spacing scale?', 'Yes — theme.extend.spacing adds keys without losing defaults.'],
  ['Why 22 palettes?', 'Coverage of every common hue plus five neutral families; each ships 11 shades (50–950), enough for complete light+dark schemes.'],
  ['Can I import only one palette?', 'JIT already does this: only classes you use compile. There is nothing to tree-shake manually.'],
  ['Does Nakshora support CSS layers?', 'Yes — opt-in @layer output on 3.1 for cascade governance.'],
  ['How do I debug generated CSS?', 'npx nakshora inspect "md:hover:bg-blue-600/50" prints the exact output.'],
  ['What Node versions are supported?', 'Node 18, 20 and 22 — CI runs the matrix; CJS entry points are require()-safe on 18.'],
  ['Is there TypeScript support?', 'Full: config typing, plugin API types, and d.ts for every package.'],
  ['How big is the core package?', '@nakshora/core has zero dependencies; the others depend only on it (plus fast-glob for Node-side file scanning).'],
  ['Why is the full build 6 MB?', 'It contains every utility × responsive variant. You should never ship it — JIT exists precisely to shrink this to kilobytes.'],
  ['Does Nakshora do purging?', 'JIT is purging by construction: only scanned classes are emitted. Safelists protect dynamic names.'],
  ['How do variants stack?', 'Screens first, then states: md:hover:bg-blue-600. They combine into a single media query with correct selector order.'],
  ['Can I nest variants infinitely?', 'Practically yes — md:dark:group-hover:focus:bg-blue-600 compiles fine. Readability is the only limit.'],
  ['What is group?', 'Mark a parent group; children use group-hover: etc. to react to the PARENT’s state. Named groups on 3.1.'],
  ['What is peer?', 'Mark a sibling peer; FOLLOWING siblings use peer-checked: etc. — the CSS-only custom checkbox trick.'],
  ['How do I style based on children?', 'has-* variants: has-[:checked]:border-blue-500 styles the parent.'],
  ['Does it support prefers-reduced-motion?', 'Yes — motion-safe: and motion-reduce: variants. Gate all animations.'],
  ['How do I handle high contrast mode?', 'forced-colors: variants keep outlines visible in Windows HCM.'],
  ['Is there a changelog?', 'Every package keeps a CHANGELOG.md; release posts summarize each version. See the Releases section.'],
  ['What happened to v1?', 'v1 is frozen at 1.0.0 (2024 design system, 1,038 classes). The file never changes; new development happens on v3.'],
  ['What changed in v2?', 'The TypeScript rewrite: programmatic generation, five themes, npm publishing. A bridge between v1 static CSS and v3 JIT.'],
  ['What changed in v3?', 'The monorepo + JIT era: four packages, content scanning, safelists, AI artifacts.'],
  ['What changed in v3.1?', 'Tailwind 3.4 parity (11,417 utilities), ten breakpoints, 155 variants, LSP, CSS-first config, dev --serve.'],
  ['Where is the roadmap?', 'The docs Modernization Roadmap and GitHub issues labeled roadmap track upcoming work.'],
  ['Can I use Nakshora in templates I sell?', 'Yes — MIT allows redistribution in commercial themes and templates.'],
  ['Do I need to credit Nakshora?', 'Not legally. We appreciate mentions, but your product UI needs no attribution.'],
  ['Is there a community?', 'GitHub discussions and issues are the hub today; community channels grow with adoption.'],
  ['How do I cite Nakshora academically?', 'Cite: Nakshora CSS Framework, Rizwan Rahim Chowdhury, RRC Development, docs.nakshora.bsdc.info.bd.'],
  ['Why do utility classes look “ugly” in HTML?', 'They look like what they DO. Readability moves from invented names to explicit declarations — most teams adapt within a week.'],
  ['Won’t my HTML get huge?', 'Markup gains classes but CSS stops growing. Total bytes and cache behavior improve dramatically — that’s the trade utility-first wins.'],
  ['Is utility-first maintainable at scale?', 'It was designed for scale: fixed vocabulary, no dead CSS, refactor-by-deletion. The largest Tailwind-style codebases run this way.'],
  ['Can designers use Nakshora?', 'Yes — the token scale is the design contract. Designers edit tokens; developers consume utilities.'],
  ['How do I enforce design constraints?', 'Tokens + corePlugins + lint rules. Removing off-scale values is a config decision, not a discipline battle.'],
  ['Does Nakshora work with CSS Modules?', 'They coexist: utilities for shared patterns, modules for truly bespoke islands.'],
  ['Can I use !important?', 'Two sanctioned ways: the ! class prefix (per-utility) or the important config option (global/scoped).'],
  ['How do I override a component?', 'Utilities after the component class, or a later stylesheet layer. Components are plain CSS — no specificity fortress.'],
  ['What is the class naming scheme?', '<utility>-<scale-key> with variant prefixes: p-4, text-blue-500, md:hover:bg-blue-600. Consistent and predictable.'],
  ['Are class names stable across versions?', 'Within a major, yes. Breaking renames only in major releases, always with migration guides.'],
  ['How do I learn fastest?', 'Quick start → utilities index → cookbook. Search (Ctrl K) answers specific questions instantly.'],
  ['Is this documentation platform open?', 'It is part of the Nakshora repository — the same monorepo, versioned alongside the framework.'],
  ['Why are there four doc versions?', 'Each major release changed capabilities materially. Versioned docs keep v1 users honest and v3 users current.'],
  ['How current is this page?', 'Every page shows its version banner; content regenerates from the framework source on each release.'],
  ['Can LLMs read these docs?', 'First-class: llms.txt, per-version llms-full.md and structured JSON corpora are published for exactly that.'],
  ['How do I get support?', 'Docs search first, then GitHub issues with a playground repro. Commercial support via RRC Development.'],
  ['Where is RRC Development located?', 'RRC Development is the development company of Rizwan Rahim Chowdhury, operating from Bangladesh (.info.bd domains, worldwide delivery).'],
  ['What does “bsdc.info.bd” mean?', 'The Bangladesh-domain home of the project: nakshora.bsdc.info.bd (main site), docs.nakshora.bsdc.info.bd (docs), rrc.bsdc.info.bd (company).']
];

