function spotlightCss(cls, V) {
  const map = {
    flex: '.flex { display: flex }', grid: '.grid { display: grid }', hidden: '.hidden { display: none }',
    'p-4': '.p-4 { padding: 1rem }', 'm-4': '.m-4 { margin: 1rem }', 'mx-auto': '.mx-auto { margin-left: auto; margin-right: auto }',
    'text-center': '.text-center { text-align: center }', 'text-sm': '.text-sm { font-size: 0.875rem; line-height: 1.25rem }',
    'bg-blue-500': '.bg-blue-500 { background-color: var(--color-blue-500) }',
    'rounded-lg': '.rounded-lg { border-radius: 0.5rem }', 'rounded-full': '.rounded-full { border-radius: 9999px }',
    'shadow-md': '.shadow-md { box-shadow: 0 4px 6px -1px rgb(0 0 0 / 0.1), 0 2px 4px -2px rgb(0 0 0 / 0.1) }',
    'gap-4': '.gap-4 { gap: 1rem }', 'w-full': '.w-full { width: 100% }', 'h-screen': '.h-screen { height: 100vh }',
    'min-h-screen': '.min-h-screen { min-height: 100vh }', 'max-w-7xl': '.max-w-7xl { max-width: 80rem }',
    'max-w-prose': '.max-w-prose { max-width: 65ch }', 'items-center': '.items-center { align-items: center }',
    'justify-between': '.justify-between { justify-content: space-between }',
    'place-items-center': '.place-items-center { place-items: center }',
    absolute: '.absolute { position: absolute }', relative: '.relative { position: relative }', sticky: '.sticky { position: sticky }',
    'inset-0': '.inset-0 { inset: 0px }', 'z-50': '.z-50 { z-index: 50 }',
    truncate: '.truncate { overflow: hidden; text-overflow: ellipsis; white-space: nowrap }',
    'object-cover': '.object-cover { object-fit: cover }', 'aspect-video': '.aspect-video { aspect-ratio: 16 / 9 }',
    transition: '.transition { transition-property: color, background-color, border-color, text-decoration-color, fill, stroke, opacity, box-shadow, transform, filter, backdrop-filter; transition-timing-function: cubic-bezier(0.4, 0, 0.2, 1); transition-duration: 150ms }',
    'animate-spin': '.animate-spin { animation: spin 1s linear infinite }',
    'sr-only': '.sr-only { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0,0,0,0); white-space: nowrap; border-width: 0 }',
    container: '.container { width: 100%; margin-inline: auto; /* max-width steps per screen */ }'
  };
  if (map[cls]) return map[cls];
  if (cls.includes(':')) return `/* variant prefix compiles into the selector/condition */\n/* e.g. ${cls} → see the variants guide */`;
  if (cls.startsWith('bg-') && cls.includes('[')) return `.${cls.replace(/[\[\]#]/g, '')} { background-color: ${cls.match(/#([0-9a-f]{6})/i)?.[0] || '#…'} }`;
  if (cls.startsWith('w-[')) return `.${cls.replace(/[\[\]]/g, '\\$&')} { width: ${cls.match(/\[(.+)\]/)?.[1]} }`;
  if (cls.startsWith('grid-cols-[')) return '/* arbitrary grid template */\ngrid-template-columns: ' + (cls.match(/\[(.+)\]/)?.[1] || '') + ';';
  if (cls.startsWith('text-') && !cls.includes('-')) return `.${cls} { /* typography utility — see the reference table */ }`;
  return `.${cls} { /* see the generated reference table for the exact declaration */ }`;
}

function spotlightUses(cls) {
  const generic = [
    `Open any recipe in the [[recipes/index|recipe library]] and you will find \`${cls}\` doing structural work`,
    'Combine with responsive prefixes for breakpoint behavior',
    'Pair with state variants (hover:, focus:) for interactivity',
    'Use in components extracted in your framework of choice',
    'Audit existing projects: search for hand-written equivalents and replace them',
    'Teach your team the class — it appears in most code reviews',
    'Compose it with spacing/color utilities for complete patterns',
    'Test it in the playground before committing',
    'Check dark mode: add the dark: twin where color is involved',
    'Bookmark its reference page — the generated table never lies'
  ];
  return generic;
}

function spotlightMistakes(cls) {
  return ['Applying it on the wrong display type (some utilities only make sense on flex/grid/block)', 'Stacking a conflicting utility of the same property later in the cascade', 'Expecting layout utilities to affect inline elements without a display change', 'Forgetting responsive prefixes, hard-coding desktop assumptions'];
}

