const A11Y = [
  ['color-contrast', 'Color contrast', 'WCAG requires 4.5:1 for body text, 3:1 for large text and UI boundaries. Nakshora palettes make this a pairing discipline.', 'Contrast is a property of PAIRS. For each palette, shades 50–400 carry dark text and 600+ carry white text. Verify critical pairs once, then encode them as component classes or tokens so the decision is never reopened.'],
  ['focus-states', 'Focus states', 'Every interactive element needs a visible keyboard focus indicator.', 'Use focus-visible: for buttons and links (mouse users rarely see it), focus: for inputs. The canonical ring: focus-visible:ring-2 focus-visible:ring-blue-500 focus-visible:ring-offset-2. Never ship outline-none naked.'],
  ['keyboard-navigation', 'Keyboard navigation', 'Everything clickable must be operable with Tab, Enter, Space and arrows.', 'Semantic elements (button, a, input) give you keyboard support free. For custom widgets, add tabindex="0", role and key handlers — then test by unplugging your mouse.'],
  ['screen-readers', 'Screen reader support', 'Structure, alt text and sr-only content shape the non-visual experience.', 'Use landmarks (header, nav, main, footer), one h1, descending heading levels, alt on meaningful images and alt="" on decorative ones. sr-only carries labels that design hides.'],
  ['reduced-motion', 'Reduced motion', 'Vestibular disorders make animation harmful; respect prefers-reduced-motion.', 'Gate every animation: motion-safe:animate-bounce. Kill transitions globally with motion-reduce:transition-none on frequently-animated roots. Skeletons: pause the shimmer.'],
  ['forms-a11y', 'Accessible forms', 'Labels, errors and autocomplete make forms usable for everyone.', 'Every input gets a visible label (label element, not placeholder). Errors: text + color + icon (never color alone), announced with aria-live. Add autocomplete attributes for real-world data.'],
  ['images-a11y', 'Accessible images', 'Alt text strategy: describe purpose, not pixels.', 'Meaningful images: descriptive alt. Decorative: alt="". Complex charts: alt summary + data table. Icons in buttons: aria-label on the button. Implement with object-cover slots that force alt discipline in review.'],
  ['semantic-structure', 'Semantic structure', 'Elements chosen for meaning give accessibility for free.', 'nav for navigation, main for primary content, article for self-contained units, aside for tangents. Screen readers navigate by these landmarks — divs are invisible to them.'],
  ['touch-targets', 'Touch targets', 'Fingers need 44×44px minimum; spacing prevents mis-taps.', 'size-11 (44px) is the minimum icon button; pad smaller visuals with p-*. space-x gaps between adjacent targets. Test on real phones, not desktop devtools emulation.'],
  ['dark-mode-a11y', 'Dark mode accessibility', 'Dark schemes have their own contrast and glare rules.', 'Avoid pure black (#000) backgrounds — slate-950 reduces halation. Desaturate bright colors one step (blue-400 beats blue-500 on dark). Check focus rings: ring-offset colors must match the dark surface.'],
  ['tables-a11y', 'Accessible tables', 'Data tables need headers, captions and scope.', 'Use th for headers, caption for the table title, and keep layout tables out of data. For responsive overflow tables, add a descriptive aria-label since scrolling hides columns.'],
  ['a11y-audit', 'Accessibility audit checklist', 'A repeatable audit you can run on any Nakshora project.', 'Run in order: (1) unplug mouse, complete every task; (2) screen reader smoke test; (3) axe/Lighthouse ≥ 95 a11y; (4) contrast-pair review; (5) reduced-motion pass; (6) zoom to 200% — no loss of content.']
];

