// ================================================================ DESIGN
const DESIGN = [
  ['color-theory', 'Color theory for interfaces', 'Hue, saturation and lightness drive emotion and hierarchy; the 60-30-10 rule keeps schemes disciplined.', 'Pick one dominant hue, one neutral family, one accent. Use saturation for energy and lightness for hierarchy — never both at once. Nakshora’s 22 palettes give you every hue; your discipline is choosing three.'],
  ['spacing-systems', 'Spacing systems', 'A single scale creates rhythm: 4px base, doubling landmarks, consistent application.', 'Adopt the Nakshora scale as law: micro gaps 1–2, component padding 4–6, section rhythm 12–24. When spacing feels wrong, it is almost always a scale jump of more than one step.'],
  ['typography-scale', 'Typography scales', 'Size, weight and leading form a scale; using steps deliberately creates hierarchy.', 'Build a ladder: display (4xl–6xl), title (2xl–3xl), heading (xl), body (base), meta (sm/xs). Each rung changes at least two properties (size AND weight) so hierarchy reads instantly.'],
  ['hierarchy', 'Visual hierarchy', 'Size, weight, color and space rank content; users read rank before words.', 'Exactly one primary action per view. Exactly one h1. Mute everything secondary by two steps. Test by squinting: the intended order should survive the blur.'],
  ['whitespace', 'Whitespace as design', 'Empty space is not wasted space; it is the luxury signal and the readability engine.', 'Double your instinctive section padding, then add 50% more. Whitespace around a CTA raises conversion more than any copy change. On this scale: sections py-16 → py-24.'],
  ['dark-mode-design', 'Designing dark mode', 'Dark is not inverted light: desaturate, elevate with surfaces, and manage glare.', 'Never pure black (use slate-950). Desaturate accents one shade. Replace shadows with lighter surfaces (elevation = lightness). Test dark-first products in bright rooms.'],
  ['glassmorphism-design', 'Glassmorphism done right', 'Frosted glass needs contrast management, subtle borders and a busy-enough backdrop.', 'Glass fails on flat backgrounds — it needs color or image behind it. Keep blur 8–16px, background alpha 50–70%, and add a 1px white/20 border to define the edge. Use the .glass component for all three.'],
  ['neon-design', 'Neon cyber aesthetics', 'Glow is power: dark canvases, saturated strokes, and restraint.', 'One or two glow colors maximum. Dark slate-950 canvas. Glows belong on interactive and hero elements — everything else stays flat. The .neon-* components encode this discipline.'],
  ['brutalism-design', 'Brutalist design', 'Raw structure: hard borders, flat color, loud type, zero decoration.', 'Thick 2px borders, offset hard shadows (4px, no blur), uppercase black-weight type and clashing primaries used sincerely. Brutalism fails halfway — commit or choose minimalism.'],
  ['minimalism-design', 'Minimalism that works', 'Minimalism is subtraction with intent: every remaining element earns its place.', 'One typeface, two grays, one accent. Hairline borders, generous whitespace, no shadows. Minimalism punishes inconsistency — align to an 8px grid religiously.'],
  ['mobile-design', 'Mobile-first design', 'Designing from the smallest screen forces priority decisions that improve every size.', 'Start each screen as a 375px single column. Every desktop affordance must survive the squeeze test. Thumbs own the bottom third: put primary actions there.'],
  ['content-first', 'Content-first design', 'Real content breaks beautiful mockups; design with it from day one.', 'Write headlines at real length, load 20 real cards, test the 3-word and 30-word cases. Nakshora utilities (truncate, line-clamp, min-w-0) are your content-defense kit.'],
  ['responsive-strategy', 'Responsive design strategy', 'Breakpoints belong to your content, not to device catalogs.', 'Grow the viewport until something breaks; fix it with the nearest prefix; repeat. Document what changes at each screen in your design system. Ten built-in screens cover almost every case.'],
  ['design-tokens-in-practice', 'Design tokens in practice', 'Tokens turn taste into policy: name decisions once, consume them everywhere.', 'Define semantic layers: color.bg.page → slate-50; color.action.primary → blue-600. Components may only consume semantic tokens. Review rule: raw palette names in components = rejected PR.'],
  ['microinteractions', 'Microinteractions', 'Sub-300ms responses make interfaces feel alive; longer ones feel sluggish.', 'Buttons: 150ms color/scale. Reveals: 200–300ms ease-out. Loading: skeleton at 300ms, spinner after 1s. Every microinteraction gets a motion-safe gate.'],
  ['docs-design', 'Designing documentation', 'Docs are product surfaces: they need hierarchy, search and relentless consistency.', 'This platform demonstrates the pattern: fixed sidebar IA, centered 65ch prose, right TOC rail, breadcrumbs everywhere, search as first-class citizen. Copy the skeleton recipe.'],
  ['brand-systems', 'Brand systems for developers', 'Brand is a token set plus rules; consistency compounds into recognition.', 'Encode brand as: primary palette, one display voice, one radius, one shadow style, one motion curve. Ship them as a preset; audit quarterly against real screenshots.'],
  ['a11y-driven-design', 'Accessibility-driven design', 'Accessible design is better design for everyone: constraints breed clarity.', 'Contrast requirements simplify palettes. Focus states expose navigation models. Alt text forces content audits. Designing for the constraint first is faster than retrofitting compliance later.']
];

